    std::cout << biggest<std::string>("pear", "apple") << "\n";
}

#include <iostream>

template <typename T>
T biggest(T a, T b) {
    return a > b ? a : b;
}

int main() {
    std::cout << biggest(2, 2.5) << "\n";
}
